$ErrorActionPreference = "Stop"

Write-Host "=== UPGRADE ROLE PEGAWAI ===" -ForegroundColor Cyan
Write-Host "Role: Pegawai Tetap, PKWT, Tenaga Ahli, Magang"

$root = (Get-Location).Path
$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupDir = Join-Path $root ("backup-role-upgrade-" + $timestamp)
New-Item -ItemType Directory -Path $backupDir -Force | Out-Null

# Backup database aktif terlebih dahulu
$dbFile = Join-Path $root "data\absensi.sqlite"
if (Test-Path $dbFile) {
    $dbBackupDir = Join-Path $backupDir "data"
    New-Item -ItemType Directory -Path $dbBackupDir -Force | Out-Null
    Copy-Item $dbFile (Join-Path $dbBackupDir "absensi.sqlite") -Force
    Write-Host "Backup database OK" -ForegroundColor Green
}

function Write-PatchedFile {
    param(
        [string]$RelativePath,
        [string]$Base64Content
    )

    $target = Join-Path $root $RelativePath
    if (-not (Test-Path $target)) {
        throw "File tidak ditemukan: $RelativePath"
    }

    $backupTarget = Join-Path $backupDir $RelativePath
    $backupParent = Split-Path $backupTarget -Parent
    New-Item -ItemType Directory -Path $backupParent -Force | Out-Null
    Copy-Item $target $backupTarget -Force

    $bytes = [Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($target, $bytes)
    Write-Host ("Patch OK: " + $RelativePath) -ForegroundColor Green
}

